import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.z3u3TMv0.js";const h=JSON.parse('{"title":"Configure image gen in MiniTavern","description":"Settings → Image gen → Image gen link — connect local A1111 / ComfyUI or cloud image APIs.","frontmatter":{"title":"Configure image gen in MiniTavern","description":"Settings → Image gen → Image gen link — connect local A1111 / ComfyUI or cloud image APIs.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Configure image gen in MiniTavern · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Settings → Image gen → Image gen link — connect local A1111 / ComfyUI or cloud image APIs."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/local/image-gen/connect-app"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/local/image-gen/connect-app"}]]},"headers":[],"relativePath":"en/local/image-gen/connect-app.md","filePath":"en/local/image-gen/connect-app.md","lastUpdated":1787224147000}'),i={name:"en/local/image-gen/connect-app.md"};function r(d,e,l,s,g,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="configure-image-gen-in-minitavern" tabindex="-1">Configure image gen in MiniTavern <a class="header-anchor" href="#configure-image-gen-in-minitavern" aria-label="Permalink to &quot;Configure image gen in MiniTavern&quot;">​</a></h1><p>App path: <strong>Settings → Image gen → Image gen link</strong>.</p><p>Image parameters, reply images, and keyword triggers: <a href="/ultra_guides/en/manual/model-link#image-gen-link--reply-images--keywords">Model link · Image gen</a>.</p><h2 id="create-an-image-gen-link" tabindex="-1">Create an image gen link <a class="header-anchor" href="#create-an-image-gen-link" aria-label="Permalink to &quot;Create an image gen link&quot;">​</a></h2><ol><li>Open MiniTavern → bottom <strong>Settings</strong>.</li><li><strong>Image gen</strong> → <strong>Image gen link</strong>.</li><li>Tap <strong>New</strong>.</li><li>Pick a <strong>platform</strong>, fill Base URL / API Key / model (varies by platform).</li><li><strong>Test</strong>, then save and set as default (if the list supports it).</li></ol><h2 id="local-a1111" tabindex="-1">Local A1111 <a class="header-anchor" href="#local-a1111" aria-label="Permalink to &quot;Local A1111&quot;">​</a></h2><p>First finish <a href="./a1111">A1111 install with <code>--api --listen</code></a>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Example</th></tr></thead><tbody><tr><td>Platform</td><td><strong>A1111(SD WebUI)</strong> (or custom A1111 protocol)</td></tr><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:7860</code></td></tr><tr><td>API Key</td><td>Usually empty; fill if WebUI uses <code>--api-auth</code></td></tr><tr><td>Model</td><td>Empty or a WebUI checkpoint name (follow App list)</td></tr></tbody></table><p>Replace <code>YOUR_PC_IP</code> with the PC LAN IP.<br><strong>Do not</strong> use <code>http://127.0.0.1:7860</code> (that is the PC itself, not the phone).</p><h2 id="local-comfyui" tabindex="-1">Local ComfyUI <a class="header-anchor" href="#local-comfyui" aria-label="Permalink to &quot;Local ComfyUI&quot;">​</a></h2><p>First finish <a href="./comfyui">ComfyUI install with <code>--listen</code></a>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Example</th></tr></thead><tbody><tr><td>Platform</td><td><strong>ComfyUI</strong> (or custom ComfyUI protocol)</td></tr><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:8188</code> (Desktop often <code>:8000</code>)</td></tr><tr><td>API Key</td><td>Usually empty</td></tr><tr><td>Model / checkpoint</td><td>Follow the list the App fetches; files must exist on the machine</td></tr></tbody></table><p>If Test fails: open the same Base URL in the phone browser to rule out firewall or missing listen.</p><h2 id="cloud-image-gen-optional" tabindex="-1">Cloud image gen (optional) <a class="header-anchor" href="#cloud-image-gen-optional" aria-label="Permalink to &quot;Cloud image gen (optional)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>When</th></tr></thead><tbody><tr><td>ChatGPT(OpenAI)</td><td>Official Images API (usually paid)</td></tr><tr><td>Gemini(Google)</td><td>Gemini image models (mostly paid — follow Google pricing)</td></tr><tr><td>OpenRouter</td><td>Route to image-capable upstreams</td></tr><tr><td>Qwen</td><td>Wanxiang / Qwen-Image (see Bailian free quota)</td></tr><tr><td>Custom (OpenAI Images)</td><td>SiliconFlow, Agnes, and other <code>/images/generations</code> gateways (image-to-image also uses generations, not <code>/images/edits</code>)</td></tr></tbody></table><p>Free cloud and Key tips: <a href="/ultra_guides/en/free-cloud/#free-image-generation">Free cloud · Image gen</a>.</p><h2 id="image-gen-in-chat" tabindex="-1">Image gen in chat <a class="header-anchor" href="#image-gen-in-chat" aria-label="Permalink to &quot;Image gen in chat&quot;">​</a></h2><p>After a default image link is set (you also need a main chat model to analyze / rewrite prompts):</p><table tabindex="0"><thead><tr><th>Entry</th><th>Description</th></tr></thead><tbody><tr><td>Type <code>/imagine prompt</code></td><td>Free image gen. The main model first decides whether the request is chat-related (e.g. “a selfie of you” → dialogue + character refs) or unrelated (e.g. “a photo of a puppy”). You can attach images in the input: the main model sees them when writing the prompt and uses them as refs; with or without attachments it still decides character/user images separately. Attachments show as small previews on the image-gen bubble. Count follows <strong>Image gen settings → Generation count</strong>. Failures leave a bubble with retry</td></tr><tr><td><code>/imagine scene</code> or Attach → From story</td><td>Draw the current scene from recent dialogue, fixed 1 image</td></tr><tr><td><code>/imagine last</code> or Attach → From last message</td><td>Draw from the last message, fixed 1 image</td></tr><tr><td><code>/imagine background</code> or Attach → Generate background</td><td>Environment background, fixed 1 image</td></tr><tr><td>Long-press bubble → Image gen</td><td>Draw from that bubble, fixed 1 image</td></tr><tr><td>Reply images (smart / keyword)</td><td>Enable “Reply images” in image settings and pick a trigger. After a normal message (attachments OK), side-path image gen from the chat, fixed 1 image; attachments are style refs</td></tr></tbody></table><p>With no image link, the four attachment modes or sending <code>/imagine</code> show “Go to settings / Cancel” — no Toast and the input is not cleared. Smart / keyword auto image gen without a link uses Toast. Enabling “Reply images” without a link also shows a modal and keeps the switch off.</p><p>Image link only, no chat model: entries that need rewrite will fail.</p><h2 id="quick-troubleshooting" tabindex="-1">Quick troubleshooting <a class="header-anchor" href="#quick-troubleshooting" aria-label="Permalink to &quot;Quick troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>Test fail / timeout</td><td>PC service running? <code>--api</code> / <code>--listen</code>? IP and port? Same Wi‑Fi?</td></tr><tr><td>PC browser OK, phone not</td><td>Firewall; guest isolation; used <code>127.0.0.1</code></td></tr><tr><td>A1111 404</td><td>Missing <code>--api</code>; Base URL has an extra path</td></tr><tr><td>Comfy spins forever</td><td>Comfy queue/errors on PC; OOM; no usable checkpoint</td></tr><tr><td>Refs but wrong face (Comfy)</td><td>Default workflow ignores refs → switch to A1111 or cloud</td></tr><tr><td><code>/imagine</code> failure bubble vanishes</td><td>Failures leave the bubble with retry; Stop still removes unfinished placeholders</td></tr></tbody></table><p>Fuller chat error codes: <a href="/ultra_guides/en/manual/errors">Error codes</a>.</p>',24)])])}const p=t(i,[["render",r]]);export{h as __pageData,p as default};
